-- MAHMS API database schema (PostgreSQL)
-- Mpilo Central Hospital, team doodoobops.
--
-- Server ids are UUIDs, generated by the database. The Android app keeps its own
-- Room row ids (auto-increment Long), so every table the app writes to also has a
-- client_ref column: the app sends its local id there and the server treats it as a
-- unique key. That makes a repeated POST idempotent (a retry after a dropped
-- connection updates the same row instead of creating a second one) and lets the app
-- match a server row back to its local record.
--
-- Run order: this file, then mahms_seed.sql.

DROP TABLE IF EXISTS receipts CASCADE;
DROP TABLE IF EXISTS payments CASCADE;
DROP TABLE IF EXISTS medication_reminders CASCADE;
DROP TABLE IF EXISTS prescriptions CASCADE;
DROP TABLE IF EXISTS emergencies CASCADE;
DROP TABLE IF EXISTS appointments CASCADE;
DROP TABLE IF EXISTS patient_vitals CASCADE;
DROP TABLE IF EXISTS staff CASCADE;
DROP TABLE IF EXISTS doctors CASCADE;
DROP TABLE IF EXISTS patients CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS departments CASCADE;

-- Hospital departments. Referenced by doctors and staff.
CREATE TABLE departments (
    department_id   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name            TEXT NOT NULL UNIQUE,
    description     TEXT NOT NULL DEFAULT ''
);

-- One row per account that has signed in. The password itself is never stored here:
-- Firebase Authentication is the identity provider and holds the credential. This table
-- maps a verified Firebase uid / e-mail onto a hospital role.
CREATE TABLE users (
    user_id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    firebase_uid    TEXT UNIQUE,
    email           TEXT NOT NULL UNIQUE,
    full_name       TEXT NOT NULL DEFAULT '',
    phone           TEXT NOT NULL DEFAULT '',
    role            TEXT NOT NULL
                    CHECK (role IN ('Patient', 'Doctor', 'Nurse', 'Pharmacist', 'Admin', 'Responder')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE patients (
    patient_id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_ref          TEXT UNIQUE,
    user_id             UUID REFERENCES users (user_id) ON DELETE SET NULL,
    first_name          TEXT NOT NULL,
    last_name           TEXT NOT NULL DEFAULT '',
    date_of_birth       TEXT NOT NULL DEFAULT '',
    gender              TEXT NOT NULL DEFAULT '',
    phone               TEXT NOT NULL DEFAULT '',
    email               TEXT NOT NULL DEFAULT '',
    address             TEXT NOT NULL DEFAULT '',
    emergency_contact   TEXT NOT NULL DEFAULT '',
    notes               TEXT NOT NULL DEFAULT '',
    registration_date   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE doctors (
    doctor_id       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_ref      TEXT UNIQUE,
    user_id         UUID REFERENCES users (user_id) ON DELETE SET NULL,
    department_id   UUID REFERENCES departments (department_id) ON DELETE SET NULL,
    first_name      TEXT NOT NULL,
    last_name       TEXT NOT NULL DEFAULT '',
    specialization  TEXT NOT NULL DEFAULT '',
    department      TEXT NOT NULL DEFAULT '',
    phone           TEXT NOT NULL DEFAULT '',
    email           TEXT NOT NULL DEFAULT ''
);

CREATE TABLE staff (
    staff_id        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_ref      TEXT UNIQUE,
    user_id         UUID REFERENCES users (user_id) ON DELETE SET NULL,
    department_id   UUID REFERENCES departments (department_id) ON DELETE SET NULL,
    first_name      TEXT NOT NULL,
    last_name       TEXT NOT NULL DEFAULT '',
    role            TEXT NOT NULL,
    department      TEXT NOT NULL DEFAULT '',
    phone           TEXT NOT NULL DEFAULT '',
    email           TEXT NOT NULL DEFAULT ''
);

-- Vitals taken by a nurse at the queue desk.
CREATE TABLE patient_vitals (
    vitals_id       UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    patient_id      UUID NOT NULL REFERENCES patients (patient_id) ON DELETE CASCADE,
    recorded_by     UUID REFERENCES users (user_id) ON DELETE SET NULL,
    blood_pressure  TEXT NOT NULL DEFAULT '',
    temperature     NUMERIC(4, 1),
    pulse           INTEGER,
    weight          NUMERIC(5, 1),
    notes           TEXT NOT NULL DEFAULT '',
    recorded_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE appointments (
    appointment_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_ref          TEXT UNIQUE,
    patient_id          UUID NOT NULL REFERENCES patients (patient_id) ON DELETE CASCADE,
    doctor_id           UUID NOT NULL REFERENCES doctors (doctor_id) ON DELETE CASCADE,
    appointment_date    DATE NOT NULL,
    appointment_time    TEXT NOT NULL,
    status              TEXT NOT NULL DEFAULT 'Pending'
                        CHECK (status IN ('Pending', 'Confirmed', 'Completed', 'Cancelled')),
    reason              TEXT NOT NULL DEFAULT '',
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_appointments_patient ON appointments (patient_id);
CREATE INDEX idx_appointments_doctor_date ON appointments (doctor_id, appointment_date);

CREATE TABLE prescriptions (
    prescription_id     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_ref          TEXT UNIQUE,
    appointment_id      UUID REFERENCES appointments (appointment_id) ON DELETE CASCADE,
    patient_id          UUID NOT NULL REFERENCES patients (patient_id) ON DELETE CASCADE,
    doctor_id           UUID NOT NULL REFERENCES doctors (doctor_id) ON DELETE CASCADE,
    medication_name     TEXT NOT NULL,
    dosage              TEXT NOT NULL DEFAULT '',
    frequency           TEXT NOT NULL DEFAULT '',
    duration            TEXT NOT NULL DEFAULT '',
    issue_date          DATE NOT NULL DEFAULT CURRENT_DATE,
    dispensed           BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE INDEX idx_prescriptions_patient ON prescriptions (patient_id);

CREATE TABLE medication_reminders (
    reminder_id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_ref          TEXT UNIQUE,
    prescription_id     UUID REFERENCES prescriptions (prescription_id) ON DELETE CASCADE,
    patient_id          UUID NOT NULL REFERENCES patients (patient_id) ON DELETE CASCADE,
    medication_name     TEXT NOT NULL,
    dosage              TEXT NOT NULL DEFAULT '',
    -- "HH:mm", 24 hour.
    reminder_time       TEXT NOT NULL,
    is_active           BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE emergencies (
    emergency_id    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_ref      TEXT UNIQUE,
    patient_id      UUID NOT NULL REFERENCES patients (patient_id) ON DELETE CASCADE,
    -- Free text as the phone recorded it: "Address (lat, lon)", or a note when GPS was refused.
    location        TEXT NOT NULL DEFAULT '',
    latitude        DOUBLE PRECISION,
    longitude       DOUBLE PRECISION,
    status          TEXT NOT NULL DEFAULT 'Active'
                    CHECK (status IN ('Active', 'In Progress', 'Resolved')),
    description     TEXT NOT NULL DEFAULT '',
    raised_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    resolved_at     TIMESTAMPTZ
);

CREATE INDEX idx_emergencies_status ON emergencies (status);

CREATE TABLE payments (
    payment_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    client_ref      TEXT UNIQUE,
    appointment_id  UUID NOT NULL REFERENCES appointments (appointment_id) ON DELETE CASCADE,
    amount          NUMERIC(10, 2) NOT NULL CHECK (amount >= 0),
    payment_method  TEXT NOT NULL CHECK (payment_method IN ('EcoCash', 'Card', 'Cash')),
    payment_date    DATE NOT NULL DEFAULT CURRENT_DATE,
    status          TEXT NOT NULL DEFAULT 'Completed'
                    CHECK (status IN ('Pending', 'Completed', 'Failed')),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_payments_appointment ON payments (appointment_id);

-- One receipt per completed payment. receipt_no is the number the patient sees,
-- "RCP-yyyy-NNNNN", and is allocated by the database sequence below so two phones can
-- never be issued the same number (the Android-only build derived it from the local id).
CREATE SEQUENCE IF NOT EXISTS receipt_serial START 1;

CREATE TABLE receipts (
    receipt_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    payment_id      UUID NOT NULL UNIQUE REFERENCES payments (payment_id) ON DELETE CASCADE,
    receipt_no      TEXT NOT NULL UNIQUE,
    issued_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
